INSERT INTO study_notes (unit_id, topic, category, vendor, content, source_title, source_url, case_study)
SELECT id, 'Linux Filesystems, Inodes, Mounts and LVM', 'linux-operations', 'Linux', 'Linux storage troubleshooting distinguishes block devices, volume management, mounted filesystems, free data blocks and inode availability. Exhaustion at one layer can cause application errors even when another layer appears to have spare capacity.', 'Red Hat Enterprise Linux: Managing file systems', 'https://docs.redhat.com/en/documentation/red_hat_enterprise_linux/9/html/managing_file_systems/index', 'Illustrative scenario: A lab logging application reports no space left on device, but the cause is inode exhaustion from many small files rather than large files consuming all data blocks.'
FROM units WHERE name='Operating Systems'
ON DUPLICATE KEY UPDATE topic=VALUES(topic), category=VALUES(category), vendor=VALUES(vendor), content=VALUES(content), source_title=VALUES(source_title), source_url=VALUES(source_url), case_study=VALUES(case_study);

INSERT INTO study_notes (unit_id, topic, category, vendor, content, source_title, source_url, case_study)
SELECT id, 'SSH Keys, Host Verification and Secure Remote Access', 'linux-operations', 'OpenSSH', 'SSH provides encrypted remote access while verifying the server host and authenticating the user. User key authentication and server host-key verification solve different problems and both are necessary for a trustworthy connection.', 'OpenSSH manual: ssh', 'https://man.openbsd.org/ssh', 'Illustrative scenario: A learner connecting to a recreated lab VM sees a changed host-key warning and verifies the new fingerprint through the trusted lab console before updating the stored entry.'
FROM units WHERE name='Operating Systems'
ON DUPLICATE KEY UPDATE topic=VALUES(topic), category=VALUES(category), vendor=VALUES(vendor), content=VALUES(content), source_title=VALUES(source_title), source_url=VALUES(source_url), case_study=VALUES(case_study);

INSERT INTO study_notes (unit_id, topic, category, vendor, content, source_title, source_url, case_study)
SELECT id, 'Scheduled Work with cron and systemd Timers', 'linux-operations', 'Linux', 'Scheduled jobs need a defined account, environment, concurrency policy and observable outcome as well as a schedule. cron and systemd timers have different capabilities, so confirm the scheduler and distribution rather than copying syntax across them.', 'systemd.timer manual', 'https://www.freedesktop.org/software/systemd/man/latest/systemd.timer.html', 'Illustrative scenario: A lab report works in an interactive shell but fails in cron because its relative path and environment differ from the developer session.'
FROM units WHERE name='Operating Systems'
ON DUPLICATE KEY UPDATE topic=VALUES(topic), category=VALUES(category), vendor=VALUES(vendor), content=VALUES(content), source_title=VALUES(source_title), source_url=VALUES(source_url), case_study=VALUES(case_study);

INSERT INTO study_notes (unit_id, topic, category, vendor, content, source_title, source_url, case_study)
SELECT id, 'systemd Units, Journals and Resource Diagnosis', 'linux-operations', 'Linux', 'A systemd service unit declares how a service starts and is supervised; the journal records events that help explain its behaviour. Resource diagnosis combines service state, application health and host limits rather than relying on a single status flag.', 'systemd.service manual', 'https://www.freedesktop.org/software/systemd/man/latest/systemd.service.html', 'Illustrative scenario: A repeatedly restarting lab worker appears active between crashes; the learner correlates restart counts, exit status and journal timestamps before changing the restart policy.'
FROM units WHERE name='Operating Systems'
