INSERT INTO study_notes (unit_id, topic, category, vendor, content, source_title, source_url, case_study)
SELECT id, 'MongoDB Document Modelling and Schema Decisions', 'databases', 'MongoDB', 'MongoDB stores BSON documents in collections, allowing related fields and nested structures to be represented together. Flexible structure still needs a deliberate data model, validation rules and a design based on the queries and updates the application must support.', 'MongoDB Manual: Data modeling', 'https://www.mongodb.com/docs/manual/data-modeling/', 'Illustrative scenario: A synthetic asset register embeds a short location object in each asset document but references a separately managed equipment-model collection.'
FROM units WHERE name='Fundamentals of Computer Science'
ON DUPLICATE KEY UPDATE topic=VALUES(topic), category=VALUES(category), vendor=VALUES(vendor), content=VALUES(content), source_title=VALUES(source_title), source_url=VALUES(source_url), case_study=VALUES(case_study);

INSERT INTO study_notes (unit_id, topic, category, vendor, content, source_title, source_url, case_study)
SELECT id, 'MongoDB CRUD, Filters and Update Semantics', 'databases', 'MongoDB', 'CRUD operations create, read, update and delete documents, and correctness depends on precise filters and explicit expected outcomes. Use synthetic lab data and inspect the target set before any operation that changes or removes records.', 'MongoDB Manual: CRUD operations', 'https://www.mongodb.com/docs/manual/crud/', 'Illustrative scenario: A learner updates the status of one fictional lab asset by its unique _id and checks matchedCount and modifiedCount rather than assuming the command changed the intended record.'
FROM units WHERE name='Fundamentals of Computer Science'
ON DUPLICATE KEY UPDATE topic=VALUES(topic), category=VALUES(category), vendor=VALUES(vendor), content=VALUES(content), source_title=VALUES(source_title), source_url=VALUES(source_url), case_study=VALUES(case_study);

INSERT INTO study_notes (unit_id, topic, category, vendor, content, source_title, source_url, case_study)
SELECT id, 'MongoDB Indexes and explain for Query Diagnosis', 'databases', 'MongoDB', 'Indexes can reduce the documents a query must examine, but consume storage and add work to writes. Diagnose a representative query and dataset with explain rather than assuming that adding more indexes always improves the application.', 'MongoDB Manual: Explain results', 'https://www.mongodb.com/docs/manual/reference/explain-results/', 'Illustrative scenario: A lab asset search filters by status and sorts by asset identifier; the learner compares the unindexed plan with a candidate compound index using synthetic records.'
FROM units WHERE name='Fundamentals of Computer Science'
ON DUPLICATE KEY UPDATE topic=VALUES(topic), category=VALUES(category), vendor=VALUES(vendor), content=VALUES(content), source_title=VALUES(source_title), source_url=VALUES(source_url), case_study=VALUES(case_study);

INSERT INTO study_notes (unit_id, topic, category, vendor, content, source_title, source_url, case_study)
SELECT id, 'MongoDB Secure Connectivity and Service Boundaries', 'database-operations', 'MongoDB', 'A database deployment needs restricted network reachability, authenticated identities, least-privilege roles and protected transport. A connection string is configuration that can contain credentials and must be handled as a secret rather than copied into source code or screenshots.', 'MongoDB Manual: Security checklist', 'https://www.mongodb.com/docs/manual/administration/security-checklist/', 'Illustrative scenario: A training application connects to a local MongoDB instance through a dedicated lab account while the service remains inaccessible from unrelated networks.'
FROM units WHERE name='Operating Systems'
ON DUPLICATE KEY UPDATE topic=VALUES(topic), category=VALUES(category), vendor=VALUES(vendor), content=VALUES(content), source_title=VALUES(source_title), source_url=VALUES(source_url), case_study=VALUES(case_study);

INSERT INTO study_notes (unit_id, topic, category, vendor, content, source_title, source_url, case_study)
SELECT id, 'MongoDB Backup, Restore and Recovery Validation', 'database-operations', 'MongoDB', 'A backup approach must match the deployment topology, consistency needs and recovery objectives. A successful dump command is only one step; recovery requires a permitted destination, suitable tool/server compatibility and validation of the restored application data.', 'MongoDB Database Tools: mongodump', 'https://www.mongodb.com/docs/database-tools/mongodump/', 'Illustrative scenario: A learner backs up a small synthetic training database and restores it into a separate disposable target, then compares record counts and sample application queries.'
FROM units WHERE name='Operating Systems'
