INSERT INTO study_notes (unit_id, topic, category, vendor, content, source_title, source_url, case_study)
SELECT id, 'Python Automation with CSV, JSON and Validated Inputs', 'programming', 'Python', 'Python is useful for turning repeatable data-handling tasks into readable, testable automation. Validate the meaning and structure of input before generating a report or considering changes to external systems.', 'Python documentation: csv and JSON modules', 'https://docs.python.org/3/library/csv.html', 'Illustrative scenario: A lab inventory script reads a synthetic CSV, rejects duplicate asset IDs and produces a JSON summary without contacting any real equipment.'
FROM units WHERE name='Fundamentals of Computer Science'
