INSERT INTO study_notes (unit_id, topic, category, vendor, content, source_title, source_url, case_study)
SELECT id, 'Python HTTP APIs, Timeouts, Pagination and Idempotence', 'programming', 'Python', 'API automation must handle remote failure, incomplete result pages and uncertain outcomes in addition to the successful response. Begin with read-only requests to a local mock service and make timeouts, validation and retry behaviour explicit.', 'Python documentation: urllib.request', 'https://docs.python.org/3/library/urllib.request.html', 'Illustrative scenario: A mock inventory API returns results in pages and temporarily fails; the learner avoids treating the first page as a complete inventory and prevents an endless retry loop.'
FROM units WHERE name='Fundamentals of Computer Science'
ON DUPLICATE KEY UPDATE topic=VALUES(topic), category=VALUES(category), vendor=VALUES(vendor), content=VALUES(content), source_title=VALUES(source_title), source_url=VALUES(source_url), case_study=VALUES(case_study);

INSERT INTO study_notes (unit_id, topic, category, vendor, content, source_title, source_url, case_study)
SELECT id, 'Node.js Async Work, Promises and Error Boundaries', 'programming', 'Node.js', 'Node.js uses an event loop and asynchronous I/O to handle work without waiting synchronously for each network or filesystem operation. async/await makes promise-based flow readable but does not make CPU-heavy code non-blocking or automatically handle rejected operations.', 'Node.js Learn: Do not block the event loop', 'https://nodejs.org/en/learn/asynchronous-work/dont-block-the-event-loop', 'Illustrative scenario: A local report endpoint becomes unresponsive while a large synchronous calculation runs; the learner distinguishes CPU work from I/O and limits the dataset before considering a worker design.'
FROM units WHERE name='Fundamentals of Computer Science'
ON DUPLICATE KEY UPDATE topic=VALUES(topic), category=VALUES(category), vendor=VALUES(vendor), content=VALUES(content), source_title=VALUES(source_title), source_url=VALUES(source_url), case_study=VALUES(case_study);

INSERT INTO study_notes (unit_id, topic, category, vendor, content, source_title, source_url, case_study)
SELECT id, 'Node.js Packages, Configuration and a Local HTTP Service', 'programming', 'Node.js', 'A maintainable Node.js service has explicit dependencies, predictable configuration and controlled handling of requests and failures. Keep a training service bound to loopback, validate input and use supported runtime and package versions.', 'Node.js documentation: HTTP', 'https://nodejs.org/api/http.html', 'Illustrative scenario: A local training API serves synthetic inventory data while refusing unsupported methods and oversized input; its package lockfile makes the dependency selection reviewable.'
FROM units WHERE name='Fundamentals of Computer Science'
ON DUPLICATE KEY UPDATE topic=VALUES(topic), category=VALUES(category), vendor=VALUES(vendor), content=VALUES(content), source_title=VALUES(source_title), source_url=VALUES(source_url), case_study=VALUES(case_study);

INSERT INTO study_notes (unit_id, topic, category, vendor, content, source_title, source_url, case_study)
SELECT id, 'Power Chains, N+1 Capacity and Independent A/B Paths', 'facilities', 'Generic', 'Availability depends on the entire service dependency chain, not just the number of server power cords. State the load and failure scope when using N, N+1 or 2N; spare capacity alone does not establish independent distribution or maintainability.', 'ASHRAE Handbook 2023, Chapter 20: Data Centers and Telecommunication Facilities', 'https://handbook.ashrae.org/Handbooks/A23/SI/A23_Ch20/a23_ch20_si.aspx', 'Illustrative scenario: a trainee traces two labelled rack feeds and discovers that they share upstream distribution. The desk review identifies a common dependency without disconnecting either feed.'
FROM units WHERE name='Computer Systems Architecture (A+)'
ON DUPLICATE KEY UPDATE topic=VALUES(topic), category=VALUES(category), vendor=VALUES(vendor), content=VALUES(content), source_title=VALUES(source_title), source_url=VALUES(source_url), case_study=VALUES(case_study);

INSERT INTO study_notes (unit_id, topic, category, vendor, content, source_title, source_url, case_study)
SELECT id, 'UPS Selection: Watts, VA, Power Factor and Runtime Curves', 'facilities', 'Generic', 'UPS selection requires separate checks for real-power capacity, apparent-power capacity and required runtime. Use measured or documented load assumptions, anticipated growth and the exact manufacturer battery/runtime data; adding PSU labels or dividing battery nameplate energy by load does not establish product runtime.', 'Eaton UPS sizing guide', 'https://www.eaton.com/us/en-us/products/backup-power-ups-surge-it-power-distribution/backup-power-ups/ups-sizing-guide.html', 'Illustrative scenario: a synthetic rack fits a UPS watt rating but fails a separate downstream surviving-feed allocation. The learner records both checks rather than declaring the whole power path sufficient.'
FROM units WHERE name='Computer Systems Architecture (A+)'
ON DUPLICATE KEY UPDATE topic=VALUES(topic), category=VALUES(category), vendor=VALUES(vendor), content=VALUES(content), source_title=VALUES(source_title), source_url=VALUES(source_url), case_study=VALUES(case_study);

INSERT INTO study_notes (unit_id, topic, category, vendor, content, source_title, source_url, case_study)
SELECT id, 'Airflow, Inlet Readings and Energy Measurement Boundaries', 'facilities', 'Generic', 'Thermal diagnosis depends on where and when readings were taken. Supply air, a rack inlet and exhaust air describe different conditions; correlate inlet trends with airflow, fan response and workload before proposing a cause or a setpoint change. Compare energy metrics only across matching measurement boundaries and time windows.', 'DOE/NREL Best Practices Guide for Energy-Efficient Data Center Design, July 2024', 'https://www.energy.gov/sites/default/files/2024-07/best-practice-guide-data-center-design.pdf', 'Illustrative scenario: upper inlets at one training rack rise while the room average stays stable. A recent blanking-panel change is one hypothesis; sensor placement and other airflow restrictions remain competing explanations.'
FROM units WHERE name='Computer Systems Architecture (A+)'
ON DUPLICATE KEY UPDATE topic=VALUES(topic), category=VALUES(category), vendor=VALUES(vendor), content=VALUES(content), source_title=VALUES(source_title), source_url=VALUES(source_url), case_study=VALUES(case_study);

INSERT INTO study_notes (unit_id, topic, category, vendor, content, source_title, source_url, case_study)
SELECT id, 'ESD Controls, Standby Power and Authorised Service Procedures', 'hardware', 'Generic', 'A hardware procedure must match the exact product, component and maintenance state. ESD precautions protect susceptible components, while electrical isolation and safe-working procedures address different hazards. An operating-system shutdown does not necessarily remove standby power or make internal work appropriate.', 'Dell PowerEdge MX7000 service manual: safety precautions', 'https://www.dell.com/support/manuals/en-us/poweredge-mx7000/mx7000_fsm/safety-precautions?guid=guid-58747f98-609a-4a19-a64c-bf2cf7c32135&lang=en-us', 'Illustrative scenario: a learner compares two manufacturer procedures and notices that one component is documented as hot-plug while another requires a different preparation state. They record the distinction instead of treating every replaceable module alike.'
FROM units WHERE name='Computer Systems Architecture (A+)'
ON DUPLICATE KEY UPDATE topic=VALUES(topic), category=VALUES(category), vendor=VALUES(vendor), content=VALUES(content), source_title=VALUES(source_title), source_url=VALUES(source_url), case_study=VALUES(case_study);

INSERT INTO study_notes (unit_id, topic, category, vendor, content, source_title, source_url, case_study)
SELECT id, 'Predictive Hardware Alerts, Failure Domains and Recovery Evidence', 'hardware', 'Generic', 'Hardware alerts are signals to interpret with model-specific logs and service impact. Predictive storage warnings do not provide an exact failure deadline, and a clean status does not guarantee future health. Separate component diagnosis, array redundancy and independent recovery evidence before choosing an action.', 'Dell PowerEdge HDD: predicted drive failure guidance', 'https://www.dell.com/support/kbdoc/en-us/000126418/poweredge-hdd-what-is-predicted-drive-failure-and-how-to-solve-it?lang=en', 'Illustrative scenario: a synthetic incident contains a predictive-drive warning and a separate local inlet-temperature rise. The learner maintains distinct evidence trails until supported correlation exists, rather than reporting that one caused the other.'
FROM units WHERE name='Computer Systems Architecture (A+)'
ON DUPLICATE KEY UPDATE topic=VALUES(topic), category=VALUES(category), vendor=VALUES(vendor), content=VALUES(content), source_title=VALUES(source_title), source_url=VALUES(source_url), case_study=VALUES(case_study);

INSERT INTO study_notes (unit_id, topic, category, vendor, content, source_title, source_url, case_study)
SELECT id, 'Service Capacity, Availability Budgets and RPO/RTO Evidence', 'facilities', 'Generic', 'Plan for the service that must be recovered, including its dependencies and the defined failure state. CPU, memory, storage, power, cooling and network limits are separate capacity constraints. Recovery targets and simple availability arithmetic are planning inputs, not proof that an implementation meets them.', 'NIST SP 800-34 Rev. 1: Contingency Planning Guide for Federal Information Systems', 'https://csrc.nist.gov/pubs/sp/800/34/r1/upd1/final', 'Illustrative scenario: a desk recovery plan includes database data, identity and application configuration, while an existing test restored only one file. The learner identifies the evidence gap rather than claiming the full service met its target.'
FROM units WHERE name='Computer Systems Architecture (A+)'
ON DUPLICATE KEY UPDATE topic=VALUES(topic), category=VALUES(category), vendor=VALUES(vendor), content=VALUES(content), source_title=VALUES(source_title), source_url=VALUES(source_url), case_study=VALUES(case_study);

